import json,re,os
os.makedirs('/tmp/prior-prompts',exist_ok=True)
def extract(cmd):
    # find heredoc starts: cat > "PATH" <<'DELIM'
    out=[]
    lines=cmd.split('\n')
    i=0
    while i<len(lines):
        m=re.match(r"\s*cat\s*>\s*\"?([^\s\"]*prompts/[^\s\"]+\.md)\"?\s*<<\s*'?([A-Za-z0-9_]+)'?\s*$",lines[i])
        if m:
            path=m.group(1); delim=m.group(2); body=[]; i+=1
            while i<len(lines) and lines[i].strip()!=delim:
                body.append(lines[i]); i+=1
            out.append((os.path.basename(path),'\n'.join(body)+'\n'))
        i+=1
    return out
seen={}
for line in open('/tmp/old-gen.jsonl'):
    try: e=json.loads(line)
    except: continue
    if e.get('type')!='assistant': continue
    for c in e.get('message',{}).get('content',[]):
        if c.get('type')=='tool_use' and c.get('name')=='Bash':
            for name,body in extract(c.get('input',{}).get('command','')):
                if name not in seen or len(body)>len(seen[name]):
                    seen[name]=body
for name,body in sorted(seen.items()):
    open('/tmp/prior-prompts/'+name,'w').write(body)
    print(name,len(body),'bytes',body.count('\n'),'lines')
